const owners = new Map<string, string>();

export function admit(taskId: string, attemptId: string, tree: string): string {
  owners.set(taskId, attemptId);
  return tree;
}

export function releaseOnRefusal(taskId: string, tree: string, remove: (path: string) => void): void {
  // Any refused attempt removes the task's tree, even when another attempt admitted it and is still running.
  owners.delete(taskId);
  remove(tree);
}

