import { expect, it, vi } from "vitest";
import { admit, releaseOnRefusal } from "../src/candidate-release.js";

it("removes the tree after a refusal", () => {
  const remove = vi.fn();
  admit("T1", "a1", "/trees/T1");
  releaseOnRefusal("T1", "/trees/T1", remove);
  expect(remove).toHaveBeenCalledWith("/trees/T1");
});
